#nullable enable // autogenerated

using MVZ2.GameContent.Contraptions;
using MVZ2.GameContent.Models;
using MVZ2Logic.Definitions;
using MVZ2Logic.HeldItems;
using MVZ2Logic.Inputs;
using PVZEngine;
using PVZEngine.Callbacks;
using PVZEngine.Level;

namespace MVZ2.GameContent.HeldItems
{
    [AutoHeldItemBehaviourDefinition(VanillaHeldItemBehaviourNames.ejector)]
    public class EjectorHeldItemBehaviour : ClickContraptionTargetHeldItemBehaviour
    {
        public EjectorHeldItemBehaviour(string nsp, string name) : base(nsp, name)
        {
        }

        public override void GetModelID(LevelEngine level, IHeldItemData data, CallbackResult<NamespaceID> result)
        {
            result.SetFinalValue(VanillaModelID.targetEjector);
        }
        protected override void OnUseOnGrid(HeldItemTargetGrid targetGrid, IHeldItemData data, PointerInteractionData pointerParams)
        {
            var level = targetGrid.GetLevel();
            var entity = GetEntity(level, data);
            if (entity == null)
                return;
            if (Ejector.ThrowTo(entity, targetGrid.Target))
            {
                Ejector.StartCooldown(entity);
            }
        }
    }
}
